server {
    listen 80 default_server;
    server_name _;
    root /srv/sunchan/www;
    index index.php;
    client_max_body_size 8m;

    # Preserve historical incident logs while the board is browsed.
    access_log /var/log/nginx/runtime-access.log;
    error_log /var/log/nginx/runtime-error.log warn;

    location / {
        try_files $uri $uri/ /index.php?$query_string;
    }
    location = /po/ {
        rewrite ^ /index.php last;
    }
    location ^~ /uploads/ {
        alias /srv/sunchan/uploads/;
        default_type application/octet-stream;
        add_header X-Content-Type-Options nosniff always;
    }
    location ~ \.php$ {
        try_files $uri =404;
        include fastcgi_params;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
        fastcgi_pass 127.0.0.1:9000;
    }
    location ~ /\. {
        deny all;
    }
}

